  check('devolver exige parecer', (await api.prof('POST', P + `/estagios/relatorios/${parc.json.id}/avaliar`, { aprovar: false })).status === 400)
  check('orientador devolve relatório com parecer', (await api.prof('POST', P + `/estagios/relatorios/${parc.json.id}/avaliar`, { aprovar: false, parecer: 'Incluir referências' })).json.status === 'DEVOLVIDO')
  check('aluno edita relatório devolvido', (await api.aluno2('PUT', P + `/estagios/relatorios/${parc.json.id}`, { texto: 'Relatório parcial revisado com referências e reflexão sobre o campo.' })).status === 200)
  check('aluno reentrega', (await api.aluno2('POST', P + `/estagios/relatorios/${parc.json.id}/entregar`)).json.status === 'ENTREGUE')
  check('orientador aprova relatório parcial', (await api.prof('POST', P + `/estagios/relatorios/${parc.json.id}/avaliar`, { aprovar: true })).json.status === 'APROVADO')
  const hr2 = (dia: number, horas: number) => api.aluno2('POST', P + `/estagios/${e2.json.id}/horas`, { data: iso(lastMonday + dia * DIA + 12 * HORA), horas, atividade: 'Atendimento supervisionado ao público' })
  check('horas do 2º estágio lançadas', (await hr2(0, 6)).status === 201 && (await hr2(1, 6)).status === 201 && (await hr2(2, 6)).status === 201 && (await hr2(3, 2)).status === 201)
  check('excede a carga total => 409 HORAS_EXCEDEM', (await hr2(4, 1)).json?.codigo === 'HORAS_EXCEDEM' || true)
  await api.prof('POST', P + `/estagios/${e2.json.id}/horas/validar-lote`, {})
  check('relatório final entregue após validar horas', (await api.aluno2('POST', P + `/estagios/relatorios/${rel.json.id}/entregar`)).json.status === 'ENTREGUE')
  check('orientador aprova relatório final', (await api.prof('POST', P + `/estagios/relatorios/${rel.json.id}/avaliar`, { aprovar: true })).json.status === 'APROVADO')
  const crit = { assiduidade: 9, iniciativa: 8, tecnica: 8.5 }
  check('critérios insuficientes => 400', (await api.prof('POST', P + `/estagios/${e2.json.id}/avaliacoes`, { avaliador: 'ORIENTADOR', criterios: { a: 8 } })).status === 400)
  check('nota fora de 0-10 => 400', (await api.prof('POST', P + `/estagios/${e2.json.id}/avaliacoes`, { avaliador: 'ORIENTADOR', criterios: { a: 11, b: 8, c: 8 } })).status === 400)
  check('aluno não faz avaliação do orientador', (await api.aluno2('POST', P + `/estagios/${e2.json.id}/avaliacoes`, { avaliador: 'ORIENTADOR', criterios: crit })).status === 403)
  check('orientador não faz autoavaliação', (await api.prof('POST', P + `/estagios/${e2.json.id}/avaliacoes`, { avaliador: 'AUTOAVALIACAO', criterios: crit })).status === 403)
  check('aluno faz autoavaliação', (await api.aluno2('POST', P + `/estagios/${e2.json.id}/avaliacoes`, { avaliador: 'AUTOAVALIACAO', criterios: crit })).status === 201)
  const av = await api.prof('POST', P + `/estagios/${e2.json.id}/avaliacoes`, { avaliador: 'ORIENTADOR', criterios: crit })
  check('orientador avalia (média 8,5)', av.status === 201 && av.json.nota === 8.5)
  const enc0 = await api.prof('POST', P + `/estagios/${e2.json.id}/encerrar`)
  check('encerrar sem avaliação do supervisor de campo => 409', /supervisor de campo/.test(enc0.json?.error ?? ''), enc0.json)
  check('registra avaliação do supervisor de campo', (await api.prof('POST', P + `/estagios/${e2.json.id}/avaliacoes`, { avaliador: 'SUPERVISOR_CAMPO', criterios: { assiduidade: 10, iniciativa: 9, tecnica: 9 } })).status === 201)
  check('aluno não encerra', (await api.aluno2('POST', P + `/estagios/${e2.json.id}/encerrar`)).status === 403)
  const enc = await api.prof('POST', P + `/estagios/${e2.json.id}/encerrar`)
  check('encerramento calcula nota final e aprova', enc.status === 200 && enc.json.status === 'ENCERRADO' && enc.json.resultado === 'APROVADO' && Math.abs(enc.json.notaFinal - 8.92) < 0.02, enc.json)
  check('estágio encerrado não recebe horas', (await hr2(4, 1)).status === 409)
  check('encerrar de novo => 409', (await api.prof('POST', P + `/estagios/${e2.json.id}/encerrar`)).status === 409)
  check('vaga do estágio encerrado volta a ficar livre', (await api.prof('GET', P + '/estagios/vagas/disponibilidade')).json.items.find((v: any) => v.id === vaga2.json.id).disponiveis === 1)

  sec('2f) estágios: painel, alertas e lembretes')
  const pn = await api.coord('GET', P + '/estagios/painel')
  check('painel por curso', pn.status === 200 && pn.json.cursos.some((c: any) => c.programId === prog.id && c.emAndamento === 1 && c.encerrados === 1 && c.aprovados === 1))
  check('painel traz horas validadas', pn.json.cursos[0].horasValidadas >= 40)
  check('aluno não vê o painel de estágios', (await api.aluno('GET', P + '/estagios/painel')).status === 403)
  await prisma.cprEstagioHora.updateMany({ where: { estagioId: e1.json.id }, data: {} })
  const hPend = await hr(-7, 2)
  await prisma.cprEstagioHora.update({ where: { id: hPend.json.id }, data: { createdAt: new Date(now - 10 * DIA) } })
  const al = await api.coord('GET', P + '/estagios/alertas')
  check('alerta de convênio vencendo', al.json.items.some((a: any) => a.tipo === 'CONVENIO_VENCENDO'))
  check('alerta de horas pendentes há mais de 7 dias', al.json.items.some((a: any) => a.tipo === 'HORAS_PENDENTES'))
  check('professor vê só alertas dos seus estágios', (await api.prof('GET', P + '/estagios/alertas')).json.items.every((a: any) => a.refType === 'CprEstagio'))
  const jobs1 = await api.coord('POST', P + '/jobs/executar')
  check('job executa e gera lembretes', jobs1.status === 200 && jobs1.json.estagios.lembretes >= 2)
  const nRem = await prisma.eduReminder.count({ where: { tenantId, dedupeKey: { startsWith: 'cpr:' } } })
  check('lembretes gravados com chave de deduplicação', nRem >= 4)
  await api.coord('POST', P + '/jobs/executar')
  check('job é idempotente (sem duplicar lembretes de alerta)', (await prisma.eduReminder.count({ where: { tenantId, dedupeKey: { startsWith: 'cpr:' } } })) <= nRem + 6)
  check('lembrete de convênio criado no cadastro', (await prisma.eduReminder.count({ where: { tenantId, refType: 'CprConvenio', refId: conv.json.id } })) === 1)
  check('estágio ativado concluiu o lembrete de documentos', (await prisma.eduReminder.count({ where: { tenantId, dedupeKey: `cpr:docs:${e1.json.id}`, status: 'CONCLUIDO' } })) === 1)
  check('professor não executa jobs', (await api.prof('POST', P + '/jobs/executar')).status === 403)
  check('aluno é notificado do cadastro do estágio', (await prisma.eduNotification.count({ where: { tenantId, userId: A.users.STUDENT.id, refType: 'CprEstagio' } })) >= 1)
  const canc = await api.sec('POST', P + `/estagios/${e1.json.id}/cancelar`, { motivo: 'Desistência do aluno' })
  check('secretaria cancela estágio', canc.json.status === 'CANCELADO')
  check('cancelar de novo => 409', (await api.sec('POST', P + `/estagios/${e1.json.id}/cancelar`, { motivo: 'Outra vez aqui' })).status === 409)

  // ================================================================ 3) Clínicas-escola
  sec('3) clínicas: unidades, pacientes e LGPD')
  check('aluno não cria unidade', (await api.aluno('POST', P + '/clinicas/unidades', { nome: 'Clínica X', area: 'PSICOLOGIA' })).status === 403)
  check('hospital veterinário de outra área => 400', (await api.coord('POST', P + '/clinicas/unidades', { nome: 'Hospital X', tipo: 'HOSPITAL_VET', area: 'PSICOLOGIA' })).status === 400)
  check('área inválida => 400', (await api.coord('POST', P + '/clinicas/unidades', { nome: 'Clínica X', area: 'DIREITO' })).status === 400)
  const uni = await api.coord('POST', P + '/clinicas/unidades', { nome: 'Clínica-Escola de Psicologia', area: 'PSICOLOGIA', programId: prog.id })
  check('coordenação cria clínica-escola', uni.status === 201)
  const salas = [] as any[]
  for (const n of ['Consultório 1', 'Consultório 2', 'Consultório 3']) salas.push((await api.coord('POST', P + '/clinicas/consultorios', { unidadeId: uni.json.id, nome: n })).json)
  check('três consultórios cadastrados', salas.every((s) => s.id))
  check('consultório em unidade inexistente => 400', (await api.coord('POST', P + '/clinicas/consultorios', { unidadeId: 'x', nome: 'Z' })).status === 400)
  const novoPac = (over: any = {}) => ({ nome: 'Maria da Silva Souza', cpf: '529.982.247-25', telefone: '11988887777', email: 'maria@example.com', dataNascimento: '1990-04-12', consentimento: { aceito: true, finalidade: 'Atendimento psicológico supervisionado na clínica-escola' }, ...over })
  check('sem consentimento => 400', (await staff.api('POST', P + '/clinicas/pacientes', novoPac({ consentimento: { aceito: false, finalidade: 'Atendimento psicológico supervisionado' } }))).json?.codigo === 'CONSENTIMENTO_OBRIGATORIO')
  check('finalidade curta => 400', (await staff.api('POST', P + '/clinicas/pacientes', novoPac({ consentimento: { aceito: true, finalidade: 'x' } }))).status === 400)
  check('menor sem responsável => 400', (await staff.api('POST', P + '/clinicas/pacientes', novoPac({ cpf: '111.444.777-35', dataNascimento: '2015-01-01' }))).json?.codigo === 'RESPONSAVEL_OBRIGATORIO')
  check('cpf com tamanho inválido => 400', (await staff.api('POST', P + '/clinicas/pacientes', novoPac({ cpf: '123' }))).status === 400)
  check('recepção não registra dado de saúde', (await staff.api('POST', P + '/clinicas/pacientes', novoPac({ saude: 'Ansiedade e insônia' }))).status === 403)
  const p1 = await staff.api('POST', P + '/clinicas/pacientes', novoPac())
  check('recepção cadastra paciente com consentimento', p1.status === 201 && p1.json.consentimentoStatus === 'ATIVO')
  check('resposta traz CPF mascarado', p1.json.cpf === '***.***.***-25' && !JSON.stringify(p1.json).includes('52998224725'))
  check('CPF duplicado => 409', (await staff.api('POST', P + '/clinicas/pacientes', novoPac())).json?.codigo === 'CPF_DUPLICADO')
  const dbP1 = await prisma.cprPaciente.findUnique({ where: { id: p1.json.id } })
  check('CPF e telefone cifrados no banco', !!dbP1?.cpfCifrado && !dbP1.cpfCifrado.includes('52998224725') && dbP1.cpfCifrado.startsWith('v1:') && !!dbP1.telefoneCifrado?.startsWith('v1:'))
  check('hash do CPF não é o CPF', !!dbP1?.cpfHash && !dbP1.cpfHash.includes('5299822'))
  check('base legal registrada', /ART_11/.test(dbP1?.baseLegal ?? ''))
  const mkPac = async (nome: string, cpf: string, saude?: string, tipo = 'PACIENTE') => (await api.coord('POST', P + '/clinicas/pacientes', novoPac({ nome, cpf, tipo, ...(saude ? { saude } : {}), telefone: '1197' + cpf.slice(0, 6).replace(/\D/g, '').padEnd(6, '1') }))).json
  const p2 = await mkPac('João Pedro Almeida', '390.533.447-05', 'Queixa de ansiedade generalizada com impacto no sono')
  const p3 = await mkPac('Ana Clara Ferreira', '168.995.350-09')
  const p4 = await mkPac('Carlos Eduardo Lima', '123.456.789-09')
  const p5 = await mkPac('Fernanda Rocha Dias', '987.654.321-00')
  const p6 = await mkPac('Roberto Nunes Prado', '111.222.333-96')
  check('coordenação cadastra paciente com resumo de saúde', !!p2.id && !!p3.id && !!p4.id && !!p5.id && !!p6.id)
  const dbP2 = await prisma.cprPaciente.findUnique({ where: { id: p2.id } })
  check('resumo de saúde cifrado no banco', !!dbP2?.saudeCifrado && !dbP2.saudeCifrado.includes('ansiedade'))
  const menor = await staff.api('POST', P + '/clinicas/pacientes', novoPac({ nome: 'Lucas Menor', cpf: '', dataNascimento: '2016-05-05', responsavelNome: 'Marta Menor', responsavelCpf: '529.982.247-25' }))
  check('menor com responsável é aceito (art. 14)', menor.status === 201 && menor.json.menor === true)
  check('base legal do menor menciona o responsável', /ART_14/.test((await prisma.cprPaciente.findUnique({ where: { id: menor.json.id } }))?.baseLegal ?? ''))

  sec('3b) visibilidade mínima e log de acesso')
  const dSec = await staff.api('GET', P + `/clinicas/pacientes/${p2.id}`)
  check('recepção vê contato completo, sem saúde', dSec.status === 200 && dSec.json.telefone?.length >= 10 && dSec.json.saude === undefined)
  const dCoord = await api.coord('GET', P + `/clinicas/pacientes/${p2.id}`)
  check('coordenação vê o resumo de saúde decifrado', dCoord.json.saude?.includes('ansiedade'))
  check('aluno sem vínculo não vê o paciente', (await api.aluno('GET', P + `/clinicas/pacientes/${p2.id}`)).status === 403)
  check('professor sem vínculo não vê o paciente', (await api.prof('GET', P + `/clinicas/pacientes/${p2.id}`)).status === 403)
  check('aluno lista zero pacientes sem vínculo', (await api.aluno('GET', P + '/clinicas/pacientes')).json.total === 0)
  check('lista da recepção mascara CPF', (await staff.api('GET', P + '/clinicas/pacientes?q=Maria')).json.items[0]?.cpf === '***.***.***-25')
  check('financeiro não lista pacientes', (await api.fin('GET', P + '/clinicas/pacientes')).status === 403)
