  check('log registra a leitura da coordenação', logs.json.items.some((l: any) => l.acao === 'LEITURA' && l.userId === A.users.COORDINATOR.id))
  check('log registra os acessos negados', logs.json.items.filter((l: any) => l.acao === 'NEGADO').length >= 2)
  check('trilha central da LGPD também registra', (await prisma.lgpAcessoSensivel.count({ where: { tenantId, titularId: p2.id } })) >= 2)
  check('PATCH de contato pela recepção', (await staff.api('PATCH', P + `/clinicas/pacientes/${p3.id}`, { telefone: '11977776666' })).status === 200)
  check('recepção não altera saúde', (await staff.api('PATCH', P + `/clinicas/pacientes/${p3.id}`, { saude: 'algo' })).status === 403)

  sec('3c) escalas de supervisão')
  const escBody = (over: any = {}) => ({ unidadeId: uni.json.id, programId: prog.id, supervisorUserId: A.users.TEACHER.id, inicio: iso(T(14)), fim: iso(T(18)), capacidadeSimultanea: 2, alunos: [st0.id], ...over })
