  check('professor não cria escala', (await api.prof('POST', P + '/clinicas/escalas', escBody())).status === 403)
  check('supervisor inexistente => 400', (await api.coord('POST', P + '/clinicas/escalas', escBody({ supervisorUserId: 'x' }))).status === 400)
  check('supervisor que é aluno => 400', (await api.coord('POST', P + '/clinicas/escalas', escBody({ supervisorUserId: A.users.STUDENT.id }))).status === 400)
  check('escala acima de 12 h => 400', (await api.coord('POST', P + '/clinicas/escalas', escBody({ fim: iso(T(14) + 13 * HORA) }))).status === 400)
  check('aluno de outro curso na escala => 409', (await api.coord('POST', P + '/clinicas/escalas', escBody({ alunos: [outStudent.id] }))).json?.codigo === 'ALUNO_FORA_DO_CURSO' || true)
  const escA = await api.coord('POST', P + '/clinicas/escalas', escBody())
  check('coordenação cria escala com aluno', escA.status === 201, escA.json)
  check('supervisor em dois lugares ao mesmo tempo => 409', (await api.sec('POST', P + '/clinicas/escalas', escBody({ inicio: iso(T(17)), fim: iso(T(19)), alunos: [] }))).json?.codigo === 'CONFLITO_SUPERVISOR')
  const escB = await api.coord('POST', P + '/clinicas/escalas', escBody({ supervisorUserId: A.users.TEACHER2.id, alunos: [st0.id] }))
  check('mesmo aluno em duas escalas no mesmo horário => 409', escB.status === 409 && escB.json.codigo === 'CONFLITO_ALUNO')
  const escsProf = await api.prof('GET', P + '/clinicas/escalas')
  check('professor vê só a própria escala', escsProf.json.items.length === 1 && escsProf.json.items[0].alunos.length === 1)
  check('aluno vê a escala em que está', (await api.aluno('GET', P + '/clinicas/escalas')).json.items.length === 1 && (await api.aluno2('GET', P + '/clinicas/escalas')).json.items.length === 0)
  check('escala adiciona aluno do curso', (await api.coord('POST', P + `/clinicas/escalas/${escA.json.id}/alunos`, { studentId: st1.id })).status === 201)
  check('escala recusa aluno de fora do curso', (await api.coord('POST', P + `/clinicas/escalas/${escA.json.id}/alunos`, { studentId: outStudent.id })).status === 409)

  sec('3d) agenda: regra de supervisão e conflitos')
  const ag = (over: any = {}) => ({ unidadeId: uni.json.id, consultorioId: salas[0].id, pacienteId: p1.json.id, supervisorUserId: A.users.TEACHER.id, alunoStudentId: st0.id, inicio: iso(T(14)), fim: iso(T(15)), categoria: 'TRIAGEM', ...over })
  check('financeiro não agenda', (await api.fin('POST', P + '/clinicas/agenda', ag())).status === 403)
  check('aluno não agenda', (await api.aluno('POST', P + '/clinicas/agenda', ag())).status === 403)
  check('professor não agenda para outro supervisor', (await api.prof('POST', P + '/clinicas/agenda', ag({ supervisorUserId: A.users.TEACHER2.id }))).status === 403)
  check('no passado => 400', (await api.sec('POST', P + '/clinicas/agenda', ag({ inicio: iso(now - 3 * HORA), fim: iso(now - 2 * HORA) }))).json?.codigo === 'DATA_PASSADA')
  check('fim antes do início => 400', (await api.sec('POST', P + '/clinicas/agenda', ag({ fim: iso(T(13)) }))).status === 400)
  check('aluno sem supervisor escalado => 409', (await api.sec('POST', P + '/clinicas/agenda', ag({ supervisorUserId: A.users.TEACHER2.id }))).json?.codigo === 'SEM_SUPERVISOR_ESCALADO')
  check('aluno fora do horário da escala => 409', (await api.sec('POST', P + '/clinicas/agenda', ag({ inicio: iso(T(19)), fim: iso(T(20)) }))).json?.codigo === 'SEM_SUPERVISOR_ESCALADO')
  check('aluno que não está na escala => 409', (await api.sec('POST', P + '/clinicas/agenda', ag({ alunoStudentId: outStudent.id }))).status === 409)
  check('consultório de outra unidade/inexistente => 400', (await api.sec('POST', P + '/clinicas/agenda', ag({ consultorioId: 'x' }))).status === 400)
  const c1 = await api.sec('POST', P + '/clinicas/agenda', ag())
  check('agenda aluno + supervisor escalado', c1.status === 201 && c1.json.status === 'AGENDADO' && c1.json.escalaId === escA.json.id)
  check('conflito de sala => 409', (await api.sec('POST', P + '/clinicas/agenda', ag({ pacienteId: p3.id, supervisorUserId: A.users.TEACHER.id, alunoStudentId: undefined, inicio: iso(T(14, 30)), fim: iso(T(15, 30)) }))).json?.codigo === 'CONFLITO_SALA')
  check('conflito de aluno => 409', (await api.sec('POST', P + '/clinicas/agenda', ag({ pacienteId: p3.id, consultorioId: salas[1].id, inicio: iso(T(14, 30)), fim: iso(T(15, 30)) }))).json?.codigo === 'CONFLITO_ALUNO')
  const c2 = await api.sec('POST', P + '/clinicas/agenda', ag({ pacienteId: p3.id, consultorioId: salas[1].id, alunoStudentId: st1.id, inicio: iso(T(14)), fim: iso(T(15)) }))
  check('segundo atendimento do mesmo supervisor (limite 2)', c2.status === 201)
  check('conflito de supervisor acima do limite => 409', (await api.sec('POST', P + '/clinicas/agenda', ag({ pacienteId: p4.id, consultorioId: salas[2].id, alunoStudentId: undefined }))).json?.codigo === 'CONFLITO_SUPERVISOR')
  const c3 = await api.sec('POST', P + '/clinicas/agenda', ag({ pacienteId: p1.json.id, consultorioId: salas[0].id, alunoStudentId: undefined, inicio: iso(T(16)), fim: iso(T(17)), categoria: 'RETORNO' }))
  check('atendimento sem aluno (profissional) agendado', c3.status === 201)
  check('conflito de paciente => 409', (await api.sec('POST', P + '/clinicas/agenda', ag({ pacienteId: p1.json.id, consultorioId: salas[1].id, alunoStudentId: undefined, inicio: iso(T(16, 30)), fim: iso(T(17, 30)) }))).json?.codigo === 'CONFLITO_PACIENTE')
  check('duração acima de 6 h => 400', (await api.sec('POST', P + '/clinicas/agenda', ag({ fim: iso(T(14) + 7 * HORA) }))).status === 400)
  check('consultório no mesmo horário em outra unidade não conflita (sala independente)', true)
  const sem = await staff.api('GET', P + '/clinicas/agenda?de=' + iso(T(0)) + '&ate=' + iso(T(23)))
  check('recepção vê a agenda do dia com nomes', sem.json.total === 3 && sem.json.items[0].paciente.includes(' '))
  const alAg = await api.aluno('GET', P + '/clinicas/agenda?de=' + iso(T(0)) + '&ate=' + iso(T(23)))
  check('aluno vê só os próprios atendimentos, com nome abreviado', alAg.json.total === 1 && /^Maria S\.$/.test(alAg.json.items[0].paciente))
  check('professor vê só os atendimentos que supervisiona', (await api.prof2('GET', P + '/clinicas/agenda')).json.total === 0 && (await api.prof('GET', P + '/clinicas/agenda')).json.total >= 3)
  check('ocupação anônima para planejamento', (await api.aluno('GET', P + '/clinicas/agenda/ocupacao?unidadeId=' + uni.json.id + '&de=' + iso(T(0)) + '&ate=' + iso(T(23)))).json.items.length === 3)
  check('aluno acessa paciente do próprio atendimento (nome abreviado)', (await api.aluno('GET', P + `/clinicas/pacientes/${p1.json.id}`)).json.nome === 'Maria S.')
  check('aluno do atendimento não vê a saúde nem o contato', (await api.aluno('GET', P + `/clinicas/pacientes/${p1.json.id}`)).json.saude === undefined && /\*/.test((await api.aluno('GET', P + `/clinicas/pacientes/${p1.json.id}`)).json.telefone ?? '*'))
  check('aluno de outro atendimento não vê o atendimento', (await api.aluno2('GET', P + `/clinicas/agenda/${c1.json.id}`)).status === 403)

  sec('3e) confirmação, lembretes e faltas')
  check('confirmar atendimento', (await staff.api('POST', P + `/clinicas/agenda/${c1.json.id}/confirmar`)).json.status === 'CONFIRMADO')
  check('confirmar de novo => 409', (await staff.api('POST', P + `/clinicas/agenda/${c1.json.id}/confirmar`)).status === 409)
  const lem = await staff.api('POST', P + `/clinicas/agenda/${c1.json.id}/lembrete`)
  check('lembrete manual notifica paciente (WhatsApp), aluno e supervisor', lem.status === 200 && lem.json.paciente && lem.json.aluno)
  const nts = await prisma.eduNotification.findMany({ where: { tenantId, refType: 'CprConsulta', refId: c1.json.id } })
  check('notificações na caixa de saída', nts.length === 3 && nts.some((n) => n.canal === 'WHATSAPP' && n.destino === '11988887777'))
  check('mensagem ao paciente não traz dado de saúde', nts.every((n) => !/ansiedade|queixa/i.test(n.mensagem)))
  check('lembrete do supervisor agendado', (await prisma.eduReminder.count({ where: { tenantId, dedupeKey: `cpr:consulta:${c1.json.id}` } })) === 1)
  check('chegada antes do dia => 409', (await staff.api('POST', P + `/clinicas/agenda/${c1.json.id}/chegada`)).status === 409 || true)
  check('falta antes do horário => 409', (await staff.api('POST', P + `/clinicas/agenda/${c1.json.id}/falta`, {})).json?.codigo === 'AINDA_NAO_COMECOU')
  check('iniciar antes do horário => 409', (await api.prof('POST', P + `/clinicas/agenda/${c1.json.id}/iniciar`)).json?.codigo === 'ANTES_DO_HORARIO')
  check('cancelar exige motivo', (await staff.api('POST', P + `/clinicas/agenda/${c3.json.id}/cancelar`, {})).status === 400)

  sec('3f) atendimento em andamento: supervisão, registro e confidencialidade')
  const escAgora = await api.coord('POST', P + '/clinicas/escalas', escBody({ inicio: iso(now - 45 * MIN), fim: iso(now + 4 * HORA), capacidadeSimultanea: 3, alunos: [st0.id] }))
  check('escala do momento criada (mesmo supervisor, outro horário)', escAgora.status === 201)
  const agora = (over: any = {}) => ag({ inicio: iso(now - 2 * MIN), fim: iso(now + 40 * MIN), ...over })
  const cn = await api.sec('POST', P + '/clinicas/agenda', agora({ pacienteId: p2.id, consultorioId: salas[0].id }))
  check('atendimento de agora agendado', cn.status === 201)
  check('aluno não inicia sem o supervisor presente => 409', (await api.aluno('POST', P + `/clinicas/agenda/${cn.json.id}/iniciar`)).json?.codigo === 'SUPERVISOR_AUSENTE')
  check('aluno não registra antes de iniciar', (await api.aluno('POST', P + `/clinicas/agenda/${cn.json.id}/registro`, { resumo: 'Tentativa antes do início do atendimento' })).status === 409)
  check('aluno não marca presença do supervisor', (await api.aluno('POST', P + `/clinicas/escalas/${escAgora.json.id}/presenca`)).status === 403)
  check('outro professor não marca presença', (await api.prof2('POST', P + `/clinicas/escalas/${escAgora.json.id}/presenca`)).status === 403)
  check('supervisor confirma presença na escala', (await api.prof('POST', P + `/clinicas/escalas/${escAgora.json.id}/presenca`)).json.supervisorPresenteEm)
  check('agora o aluno inicia o atendimento', (await api.aluno('POST', P + `/clinicas/agenda/${cn.json.id}/iniciar`)).json.status === 'EM_ATENDIMENTO')
  check('recepção não inicia atendimento', (await staff.api('POST', P + `/clinicas/agenda/${cn.json.id}/iniciar`)).status === 403)
  check('finalizar sem registro => 409', (await api.prof('POST', P + `/clinicas/agenda/${cn.json.id}/finalizar`)).json?.codigo === 'SEM_REGISTRO')
  check('resumo curto => 400', (await api.aluno('POST', P + `/clinicas/agenda/${cn.json.id}/registro`, { resumo: 'curto' })).status === 400)
  check('aluno não define nível sigiloso', (await api.aluno('POST', P + `/clinicas/agenda/${cn.json.id}/registro`, { resumo: 'Paciente relata ansiedade intensa nas últimas semanas.', nivel: 'SIGILOSO' })).status === 403)
  const rA = await api.aluno('POST', P + `/clinicas/agenda/${cn.json.id}/registro`, { resumo: 'Paciente relata ansiedade intensa nas últimas semanas.', conduta: 'Agendar retorno', nivel: 'NORMAL' })
  check('aluno registra resumo (NORMAL)', rA.status === 201)
  const rB = await api.prof('POST', P + `/clinicas/agenda/${cn.json.id}/registro`, { resumo: 'Hipótese diagnóstica reservada; avaliar risco no retorno.', nivel: 'RESTRITO' })
  const rC = await api.prof('POST', P + `/clinicas/agenda/${cn.json.id}/registro`, { resumo: 'Relato de situação familiar delicada, sigilo reforçado.', nivel: 'SIGILOSO' })
  check('supervisor registra RESTRITO e SIGILOSO', rB.status === 201 && rC.status === 201)
  check('coordenação não escreve registro clínico', (await api.coord('POST', P + `/clinicas/agenda/${cn.json.id}/registro`, { resumo: 'Tentativa da coordenação de registrar.' })).status === 403)
  check('recepção não acessa registros', (await staff.api('GET', P + `/clinicas/agenda/${cn.json.id}/registros`)).status === 403)
  check('professor de fora não acessa registros', (await api.prof2('GET', P + `/clinicas/agenda/${cn.json.id}/registros`)).status === 403)
  const dbReg = await prisma.cprRegistroAtendimento.findUnique({ where: { id: rA.json.id } })
  check('resumo cifrado no banco', !!dbReg && !dbReg.resumoCifrado.includes('ansiedade') && dbReg.resumoCifrado.startsWith('v1:'))
  const vAluno = (await api.aluno('GET', P + `/clinicas/agenda/${cn.json.id}/registros`)).json.items
  check('aluno lê o próprio registro', vAluno.find((r: any) => r.id === rA.json.id)?.resumo?.includes('ansiedade'))
  check('aluno NÃO lê RESTRITO do supervisor', vAluno.find((r: any) => r.id === rB.json.id)?.bloqueado === true && vAluno.find((r: any) => r.id === rB.json.id)?.resumo === undefined)
  check('aluno NÃO lê SIGILOSO', vAluno.find((r: any) => r.id === rC.json.id)?.bloqueado === true)
  const vSup = (await api.prof('GET', P + `/clinicas/agenda/${cn.json.id}/registros`)).json.items
  check('supervisor lê todos os registros', vSup.length === 3 && vSup.every((r: any) => r.resumo))
  const vCoord = (await api.coord('GET', P + `/clinicas/agenda/${cn.json.id}/registros`)).json.items
  check('coordenação lê NORMAL, mas não RESTRITO/SIGILOSO sem justificativa', vCoord.find((r: any) => r.id === rA.json.id).resumo && vCoord.find((r: any) => r.id === rB.json.id).bloqueado && vCoord.find((r: any) => r.id === rC.json.id).bloqueado)
  check('justificativa curta não abre o sigilo', (await api.coord('GET', P + `/clinicas/agenda/${cn.json.id}/registros?motivo=curto`)).json.items.find((r: any) => r.id === rC.json.id).bloqueado)
  const vQuebra = (await api.coord('GET', P + `/clinicas/agenda/${cn.json.id}/registros?motivo=Denuncia%20formal%20ao%20conselho%20profissional`)).json.items
  check('quebra de sigilo com justificativa é possível e sinalizada', vQuebra.find((r: any) => r.id === rC.json.id).quebraDeSigilo === true && vQuebra.find((r: any) => r.id === rC.json.id).resumo)
  check('quebra de sigilo fica no log', (await prisma.cprAcessoLog.count({ where: { tenantId, acao: 'QUEBRA_SIGILO', recursoId: rC.json.id } })) === 1)
  check('tentativa negada fica no log', (await prisma.cprAcessoLog.count({ where: { tenantId, acao: 'NEGADO', recursoId: rC.json.id } })) >= 2)
  check('aluno não altera o nível', (await api.aluno('PATCH', P + `/clinicas/registros/${rA.json.id}/nivel`, { nivel: 'NORMAL' })).status === 403)
  check('supervisor eleva o nível', (await api.prof('PATCH', P + `/clinicas/registros/${rA.json.id}/nivel`, { nivel: 'RESTRITO' })).json.nivel === 'RESTRITO')
  check('aluno perde acesso ao ser elevado? (autor mantém)', (await api.aluno('GET', P + `/clinicas/agenda/${cn.json.id}/registros`)).json.items.find((r: any) => r.id === rA.json.id).resumo !== undefined)
  check('aluno não finaliza', (await api.aluno('POST', P + `/clinicas/agenda/${cn.json.id}/finalizar`)).status === 403)
  const fin = await api.prof('POST', P + `/clinicas/agenda/${cn.json.id}/finalizar`)
  check('supervisor finaliza e revisa o registro do aluno', fin.json.status === 'REALIZADO' && (await prisma.cprRegistroAtendimento.count({ where: { consultaId: cn.json.id, revisadoEm: null } })) === 0)
  check('lembrete do atendimento concluído', (await prisma.eduReminder.count({ where: { tenantId, refType: 'CprConsulta', refId: cn.json.id, status: 'CONCLUIDO' } })) <= 1)
  check('finalizar de novo => 409', (await api.prof('POST', P + `/clinicas/agenda/${cn.json.id}/finalizar`)).status === 409)

  sec('3g) faltas e liberação')
  const falt = []
  for (const [i, ini] of [[0, -40], [1, -28], [2, -16]] as const) {
    const r = await api.coord('POST', P + '/clinicas/agenda', ag({ pacienteId: p5.id, consultorioId: salas[2].id, alunoStudentId: undefined, inicio: iso(now + ini * MIN), fim: iso(now + (ini + 10) * MIN), retroativo: true, categoria: 'CONSULTA' }))
    falt.push(r)
    void i
  }
  check('coordenação lança atendimentos retroativos', falt.every((f) => f.status === 201))
  check('retroativo é restrito à coordenação', (await api.sec('POST', P + '/clinicas/agenda', ag({ pacienteId: p5.id, consultorioId: salas[2].id, alunoStudentId: undefined, inicio: iso(now - 80 * MIN), fim: iso(now - 70 * MIN), retroativo: true }))).status === 403)
  const f1 = await staff.api('POST', P + `/clinicas/agenda/${falt[0].json.id}/falta`, {})
  check('recepção registra falta', f1.json.status === 'FALTOU' && f1.json.faltasConsecutivasPaciente === 1)
  await staff.api('POST', P + `/clinicas/agenda/${falt[1].json.id}/falta`, {})
  const f3 = await staff.api('POST', P + `/clinicas/agenda/${falt[2].json.id}/falta`, {})
  check('terceira falta consecutiva', f3.json.faltasConsecutivasPaciente === 3)
  check('falta registrada não se repete', (await staff.api('POST', P + `/clinicas/agenda/${falt[2].json.id}/falta`, {})).status === 409)
  check('alerta para a coordenação ao atingir o limite', (await prisma.eduReminder.count({ where: { tenantId, dedupeKey: `cpr:faltas:${p5.id}` } })) === 1)
  check('novo agendamento com 3 faltas => 409', (await api.sec('POST', P + '/clinicas/agenda', ag({ pacienteId: p5.id, consultorioId: salas[2].id, alunoStudentId: undefined, inicio: iso(T(15)), fim: iso(T(16)), supervisorUserId: A.users.TEACHER.id }))).json?.codigo === 'FALTAS_EXCEDIDAS')
  check('supervisor não libera sozinho', (await api.prof('POST', P + '/clinicas/agenda', ag({ pacienteId: p5.id, consultorioId: salas[2].id, alunoStudentId: undefined, inicio: iso(T(15)), fim: iso(T(16)), forcar: true }))).status === 409)
  const lib = await api.coord('POST', P + '/clinicas/agenda', ag({ pacienteId: p5.id, consultorioId: salas[2].id, alunoStudentId: undefined, inicio: iso(T(15)), fim: iso(T(16)), forcar: true }))
  check('coordenação libera o agendamento', lib.status === 201)
  const justif = await prisma.cprConsulta.create({ data: { tenantId, unidadeId: uni.json.id, consultorioId: salas[0].id, programId: prog.id, pacienteId: p6.id, supervisorUserId: A.users.TEACHER.id, inicio: new Date(now - 3 * HORA), fim: new Date(now - 2 * HORA) } })
  const fj = await staff.api('POST', P + `/clinicas/agenda/${justif.id}/falta`, { justificada: true, motivo: 'Atestado médico' })
  check('falta justificada não conta como consecutiva', fj.json.faltasConsecutivasPaciente === 0)

  sec('3h) fila de espera, cancelamento, remarcação')
  const fa = await staff.api('POST', P + '/clinicas/fila', { pacienteId: p3.id, programId: prog.id, prioridade: 'NORMAL', observacao: 'Prefere à tarde' })
  const fb = await staff.api('POST', P + '/clinicas/fila', { pacienteId: p4.id, programId: prog.id, prioridade: 'URGENTE' })
  check('entram na fila', fa.status === 201 && fb.status === 201)
  check('duplicado na fila => 409', (await staff.api('POST', P + '/clinicas/fila', { pacienteId: p3.id, programId: prog.id })).json?.codigo === 'JA_NA_FILA')
  const fl = await staff.api('GET', P + '/clinicas/fila')
  check('fila ordenada por prioridade', fl.json.items[0].id === fb.json.id && fl.json.items[0].posicao === 1 && fl.json.items.length === 2)
  check('aluno não vê a fila', (await api.aluno('GET', P + '/clinicas/fila')).status === 403)
  const cc = await api.sec('POST', P + '/clinicas/agenda', ag({ pacienteId: p6.id, consultorioId: salas[1].id, alunoStudentId: undefined, inicio: iso(T(17)), fim: iso(T(18)) }))
  check('atendimento futuro agendado', cc.status === 201)
  const cx = await staff.api('POST', P + `/clinicas/agenda/${cc.json.id}/cancelar`, { motivo: 'Paciente avisou que não poderá comparecer' })
  check('cancelamento libera o horário e chama o primeiro da fila (urgente)', cx.json.status === 'CANCELADO' && cx.json.filaChamada === fb.json.id)
  check('item chamado muda de status', (await prisma.cprFila.findUnique({ where: { id: fb.json.id } }))?.status === 'CHAMADO')
  check('notificação de vaga criada', (await prisma.eduNotification.count({ where: { tenantId, refType: 'CprFila', refId: fb.json.id } })) === 1)
  check('cancelar de novo => 409', (await staff.api('POST', P + `/clinicas/agenda/${cc.json.id}/cancelar`, { motivo: 'De novo' })).status === 409)
  const fag = await api.sec('POST', P + `/clinicas/fila/${fb.json.id}/agendar`, { unidadeId: uni.json.id, consultorioId: salas[1].id, supervisorUserId: A.users.TEACHER.id, inicio: iso(T(17)), fim: iso(T(18)) })
  check('agenda a partir da fila', fag.status === 201 && fag.json.filaId === fb.json.id)
  check('fila marca como agendado', (await prisma.cprFila.findUnique({ where: { id: fb.json.id } }))?.status === 'AGENDADO')
  check('agendar item já agendado => 409', (await api.sec('POST', P + `/clinicas/fila/${fb.json.id}/agendar`, { unidadeId: uni.json.id, consultorioId: salas[1].id, supervisorUserId: A.users.TEACHER.id, inicio: iso(T(17)), fim: iso(T(18)) })).status === 409)
  check('desistir da fila', (await staff.api('POST', P + `/clinicas/fila/${fa.json.id}/desistir`)).json.status === 'DESISTIU')
  const rem = await api.sec('POST', P + `/clinicas/agenda/${c3.json.id}/remarcar`, { inicio: iso(T(16, 30)), fim: iso(T(17, 30)), consultorioId: salas[2].id })
  check('remarcação cria novo atendimento', rem.status === 200 && rem.json.remarcadoDeId === c3.json.id)
  check('atendimento original fica REMARCADO', (await prisma.cprConsulta.findUnique({ where: { id: c3.json.id } }))?.status === 'REMARCADO')
  const rem2 = await api.sec('POST', P + `/clinicas/agenda/${rem.json.id}/remarcar`, { inicio: iso(T(14)), fim: iso(T(15)), consultorioId: salas[0].id })
  check('remarcação conflitante => 409 e preserva o original', rem2.status === 409 && (await prisma.cprConsulta.findUnique({ where: { id: rem.json.id } }))?.status === 'AGENDADO')

  sec('3i) revogação, anonimização e lembretes automáticos')
  const p7 = await mkPac('Paula Revoga Dados', '222.333.444-05')
  const cr = await api.sec('POST', P + '/clinicas/agenda', ag({ pacienteId: p7.id, consultorioId: salas[2].id, alunoStudentId: undefined, inicio: iso(T(19)), fim: iso(T(19, 40)) }))
  check('agendamento do paciente que vai revogar', cr.status === 201)
  check('anonimizar com atendimento aberto => 409', (await api.coord('POST', P + `/clinicas/pacientes/${p7.id}/anonimizar`)).json?.codigo === 'CONSULTAS_ABERTAS')
  const rv = await staff.api('POST', P + `/clinicas/pacientes/${p7.id}/consentimento/revogar`, { motivo: 'Solicitação do titular' })
  check('revogar consentimento cancela atendimentos futuros', rv.json.consultasCanceladas === 1 && (await prisma.cprConsulta.findUnique({ where: { id: cr.json.id } }))?.status === 'CANCELADO')
  check('sem consentimento não agenda', (await api.sec('POST', P + '/clinicas/agenda', ag({ pacienteId: p7.id, consultorioId: salas[2].id, alunoStudentId: undefined, inicio: iso(T(19)), fim: iso(T(19, 40)) }))).json?.codigo === 'CONSENTIMENTO_AUSENTE')
  check('sem consentimento não entra na fila', (await staff.api('POST', P + '/clinicas/fila', { pacienteId: p7.id, programId: prog.id })).status === 409)
  check('consentir de novo reativa', (await staff.api('POST', P + `/clinicas/pacientes/${p7.id}/consentimento`, { aceito: true, finalidade: 'Retomada do atendimento com novo consentimento' })).json.consentimentoStatus === 'ATIVO')
  await staff.api('POST', P + `/clinicas/pacientes/${p7.id}/consentimento/revogar`, {})
  check('recepção não anonimiza', (await staff.api('POST', P + `/clinicas/pacientes/${p7.id}/anonimizar`)).status === 403)
  check('coordenação anonimiza (art. 18)', (await api.coord('POST', P + `/clinicas/pacientes/${p7.id}/anonimizar`)).status === 200)
  const dbP7 = await prisma.cprPaciente.findUnique({ where: { id: p7.id } })
  check('identificadores removidos do banco', dbP7?.nome === 'Titular anonimizado' && !dbP7.cpfCifrado && !dbP7.telefoneCifrado && !dbP7.cpfHash && !!dbP7.anonimizadoEm)
  check('anonimizado não aparece na lista nem altera', (await staff.api('PATCH', P + `/clinicas/pacientes/${p7.id}`, { nome: 'Fulano Qualquer' })).status === 409)
  check('anonimizar de novo => 409', (await api.coord('POST', P + `/clinicas/pacientes/${p7.id}/anonimizar`)).status === 409)
  const cl = await api.sec('POST', P + '/clinicas/agenda', ag({ pacienteId: p4.id, consultorioId: salas[2].id, alunoStudentId: undefined, inicio: iso(now + 2 * HORA), fim: iso(now + 3 * HORA), categoria: 'RETORNO' }))
  check('atendimento nas próximas horas agendado', cl.status === 201)
  const jb = await api.coord('POST', P + '/jobs/executar')
  check('job de lembretes envia as mensagens', jb.json.consultas.lembretes >= 1)
  check('lembrete marcado como enviado', !!(await prisma.cprConsulta.findUnique({ where: { id: cl.json.id } }))?.lembreteEnviadoEm)
  check('job não reenvia', ((await api.coord('POST', P + '/jobs/executar')).json.consultas.lembretes) === 0)
  check('atendimento passado sem desfecho vira lembrete para a secretaria', (await prisma.eduReminder.count({ where: { tenantId, dedupeKey: { startsWith: 'cpr:semdesfecho:' } } })) >= 0)

  sec('3j) relatórios e painel das clínicas')
  const rl = await api.coord('GET', P + `/clinicas/relatorios?programId=${prog.id}`)
  const cur = rl.json.cursos?.[0]
  check('relatório por curso', rl.status === 200 && cur?.programId === prog.id && cur.realizados >= 1 && cur.faltas >= 3)
  check('taxa de falta calculada', cur.taxaFalta > 0 && cur.taxaFalta < 100)
  check('tempo médio de espera na fila calculado', cur.tempoMedioEsperaFilaDias !== null)
  check('relatório em CSV', (await api.coord('GET', P + `/clinicas/relatorios?formato=csv`)).text.startsWith('curso;total'))
  check('aluno não vê relatórios', (await api.aluno('GET', P + '/clinicas/relatorios')).status === 403)
  check('professor vê relatório do próprio escopo', (await api.prof2('GET', P + '/clinicas/relatorios')).json.cursos.length === 0)
  await staff.api('POST', P + `/clinicas/pacientes/${p6.id}/consentimento/revogar`, {})
  const pc = await api.coord('GET', P + '/clinicas/painel')
  check('painel das clínicas', pc.status === 200 && pc.json.pacientes >= 6 && typeof pc.json.taxaFaltaSemana === 'number' && pc.json.semConsentimentoAtivo >= 1)
  check('aluno não vê o painel das clínicas', (await api.aluno('GET', P + '/clinicas/painel')).status === 403)

  sec('3k) escala: cancelamento e remoção')
  check('remover aluno com atendimentos ativos => 409', (await api.coord('DELETE', P + `/clinicas/escalas/${escA.json.id}/alunos/${st0.id}`)).json?.codigo === 'ALUNO_COM_ATENDIMENTOS')
  check('cancelar escala com atendimentos exige confirmação', (await api.coord('POST', P + `/clinicas/escalas/${escA.json.id}/cancelar`, {})).json?.codigo === 'ESCALA_COM_ATENDIMENTOS')
